// Get the last processed EasyBroker contact ID from static data.
const staticData = $getWorkflowStaticData('global');
const lastId = staticData.lastEbContactId || 0;

return [{ json: { lastProcessedId: lastId } }];

// Filter only contacts newer than last processed ID.
// EB returns contacts ordered by id DESC (newest first).
const response = $input.first().json;
const lastId = $('Get Last Processed ID').first().json.lastProcessedId;

if (!response.content || !Array.isArray(response.content)) {
  // API error or empty response
  return [{ json: { newContacts: 0, error: 'No content in API response' } }];
}

const newContacts = response.content.filter(c => c.id > lastId);

if (newContacts.length === 0) {
  return [{ json: { newContacts: 0 } }];
}

// Update static data with the highest ID
const staticData = $getWorkflowStaticData('global');
staticData.lastEbContactId = Math.max(...newContacts.map(c => c.id));

// Return each new contact as a separate item (oldest first for processing order)
return newContacts
  .sort((a, b) => a.id - b.id)
  .map(contact => ({
    json: {
      newContacts: newContacts.length,
      eb_contact_id: contact.id,
      name: contact.name || null,
      phone: (contact.phone || '').replace(/[^\d]/g, ''),
      identity_phone: (() => { const raw = String(contact.phone || '').trim(); const compact = raw.replace(/[ ()-]/g, ''); return /^\+[1-9]\d{7,14}$/.test(compact) ? compact : null; })(),
      email: contact.email || null,
      property_id: contact.property_id || null,
      message: contact.message || '',
      eb_source: contact.source || 'EasyBroker',
      happened_at: contact.happened_at,
      eb_contact_internal_id: contact.contact_id || null,
      source: 'easybroker'
    }
  }));

// Merge contact data with property details and normalize for downstream.
const contact = $('Filter New Contacts').item.json;
const prop = $input.first().json;

const hasProperty = !!(prop && prop.public_id);

const propertyTitle = hasProperty
  ? prop.title
  : 'Propiedad sin identificar';

const propertyPrice = hasProperty && prop.operations && prop.operations[0]
  ? prop.operations[0].formatted_amount
  : 'Precio por confirmar';

const propertyAddress = hasProperty && prop.location
  ? (typeof prop.location === 'object' ? prop.location.name : prop.location)
  : '';

const listingType = hasProperty && prop.operations && prop.operations[0]
  ? prop.operations[0].type
  : 'venta';

// Build cache payload from EB property data
const cachePayload = hasProperty ? {
  title: prop.title,
  price: propertyPrice,
  price_numeric: prop.operations?.[0]?.amount || null,
  currency: prop.operations?.[0]?.currency || 'MXN',
  location: propertyAddress,
  property_type: prop.property_type || null,
  operation_type: listingType,
  bedrooms: prop.bedrooms || null,
  bathrooms: prop.bathrooms || null,
  area_m2: prop.construction_size || prop.lot_size || null,
  description: (prop.description || '').substring(0, 500),
  url: prop.public_url || null,
  image_url: prop.title_image_full || null,
  source: 'easybroker_api'
} : null;

return [{
  json: {
    phone: contact.phone,
    identity_phone: contact.identity_phone,
    email: contact.email,
    name: contact.name,
    message: contact.message,
    listing_id: contact.property_id,
    property_title: propertyTitle,
    property_address: propertyAddress,
    property_price: propertyPrice,
    listing_type: listingType,
    source: 'easybroker',
    eb_contact_id: contact.eb_contact_id,
    eb_source: contact.eb_source,
    cache_property_id: contact.property_id || 'unknown',
    cache_payload: cachePayload,
    has_property: hasProperty
  }
}];

// Route decision based on returning lead check and day/night.
const lead = $('Normalize Lead Data').item.json;
const db = $input.first().json;

if (!lead.phone) {
  return [{ json: { route: 'skip', reason: 'no_phone' } }];
}

const isReturning = !!db.existing_conv_id;
const sameProperty = db.same_property === true;
const isDay = db.is_day !== false;

if (isReturning && sameProperty) {
  return [{
    json: {
      route: 'returning_same',
      existing_conv_id: db.existing_conv_id,
      assigned_agent_id: db.assigned_agent_id,
      existing_mode: db.existing_mode,
      ...lead
    }
  }];
}

if (isDay) {
  return [{
    json: {
      route: 'day_auction',
      is_returning_diff: isReturning && !sameProperty,
      ...lead
    }
  }];
}

return [{
  json: {
    route: 'night_queue',
    is_returning_diff: isReturning && !sameProperty,
    ...lead
  }
}];

const data = $('Route Decision').first().json;

if (!data.assigned_agent_id) {
  return [{ json: { skip: true, reason: 'no_assigned_agent' } }];
}

return [{
  json: {
    agent_id: data.assigned_agent_id,
    conversation_id: data.existing_conv_id,
    lead_name: data.name,
    lead_phone: data.phone,
    property_title: data.property_title,
    message: `Lead recurrente (EasyBroker): ${data.name || data.phone} volvio a preguntar por ${data.property_title}. Ya lo tienes asignado.`
  }
}];

